from typing import List
from collections import defaultdict

class Solution:
    def maxSubarraySum(self, nums: List[int]) -> int:
        total = sum(nums)
        if max(nums) <= 0:
            return max(nums)

        best_no_delete = nums[0]
        cur = 0
        for x in nums:
            cur = max(x, cur + x)
            best_no_delete = max(best_no_delete, cur)

        prefix_min = defaultdict(int)
        dp = defaultdict(int)
        best = best_no_delete

        prefix = 0
        for x in nums:
            prefix += x

            if x < 0:
                dp[x] += x

            best = max(best, prefix - prefix_min[x] - dp[x])

            if x < 0:
                prefix_min[x] = min(prefix_min[x], prefix - dp[x])

        return best
